'use strict';
Object.assign(PRIORITIES,{q1:'Quan trọng, khẩn cấp',q2:'Quan trọng, không khẩn cấp',q3:'Không quan trọng, khẩn cấp',q4:'Không quan trọng, không khẩn cấp'});
function matrixChip(t){return t.priority?`<span class="matrix-chip ${t.priority}" title="${esc({q1:'Quan trọng, khẩn cấp',q2:'Quan trọng, không khẩn cấp',q3:'Không quan trọng, khẩn cấp',q4:'Không quan trọng, không khẩn cấp'}[t.priority])}">${esc(PRIORITIES[t.priority])}</span>`:'';}
function taskPreferences(){return {progress:localRead('kanban-progress')!=='off',checks:localRead('kanban-checks')==='on'};}
// Use the original compact card without its external next-step button.
taskCard=function(t,p){const pref=taskPreferences(),pct=taskPct(t);return `<article class="task-card" draggable="true" data-task="${esc(t.id)}" data-pid="${esc(p.id)}" role="button" tabindex="0"><span class="tag">${esc(t.tag||'Công việc')}</span>${matrixChip(t)}${labelChips(t)}<h3>${esc(t.title)}</h3>${t.description?'<p>'+esc(t.description.slice(0,100))+'</p>':''}${pref.progress?'<div class="progress-meta"><span>'+t.checks.filter(c=>c.done).length+'/'+t.checks.length+' mục</span><strong>'+pct+'%</strong></div>'+bar(pct,p.color):''}${pref.checks?'<ul class="card-checks">'+t.checks.map(c=>'<li class="'+(c.done?'completed':'')+'">'+(c.done?'☑ ':'☐ ')+esc(c.text)+'</li>').join('')+'</ul>':''}<div class="task-footer">${t.due?'Hạn '+dateLabel(t.due):'Chưa đặt hạn'}${t.due&&t.due<today()&&t.col!=='Done'?' · Quá hạn':''}</div></article>`;};
const baseBoardUX=board;board=function(){const pref=taskPreferences();return '<div class="kanban-options"><label><input type="checkbox" data-kanban-option="progress" '+(pref.progress?'checked':'')+'> Thanh tiến độ</label><label><input type="checkbox" data-kanban-option="checks" '+(pref.checks?'checked':'')+'> Hiện checklist trên thẻ</label></div>'+baseBoardUX();};
const baseDashboardUX=dashboard;dashboard=function(){const overdue=allTasks().filter(t=>t.col!=='Done'&&(t.end?.slice(0,10)||t.due)&& (t.end?.slice(0,10)||t.due)<today()).length;return baseDashboardUX().replace('<p class="chart-foot">','<div class="overdue-total">Quá hạn <strong>'+overdue+'</strong><small>Công việc chưa hoàn tất, đã qua ngày kết thúc</small></div><p class="chart-foot">');};
const baseTimelineTaskUX=timelineTask;timelineTask=function(t){return baseTimelineTaskUX(t).replace('</button>',matrixChip(t)+bar(taskPct(t),t.project.color)+'</button>');};
const baseCalendarUX=workCalendar;workCalendar=function(){return baseCalendarUX().replace(/(<button class="month-event[\s\S]*?data-task="([^"]+)"[\s\S]*?data-pid="([^"]+)"[\s\S]*?)(<\/button>)/g,(whole,body,id,pid,end)=>{const p=project(pid),t=p?.tasks.find(t=>t.id===id);return t?body+matrixChip(t)+'<span class="calendar-progress">'+taskPct(t)+'%</span>'+bar(taskPct(t),p.color)+end:whole;});};
taskDetail=function(p,t){taskForm(p,t);const body=$('#editor-body'),form=$('#editor-form'),next=p.columns[p.columns.indexOf(t.col)+1];body.insertAdjacentHTML('afterbegin','<p class="eyebrow">'+esc(p.name)+' · Chi tiết công việc</p><div class="detail-actions"><button class="btn" type="button" data-files="'+esc(p.id)+'" data-file-task="'+esc(t.id)+'">'+svgIcon('attach')+'Tệp đính kèm</button>'+(next?'<button class="btn" type="button" id="detail-next">Chuyển sang '+esc(next)+' →</button>':'')+'<button type="button" class="btn danger" data-action="delete-task">Xóa</button></div>'+matrixChip(t));body.insertAdjacentHTML('beforeend','<h3>Checklist</h3>'+t.checks.map((c,i)=>`<div class="inline-check"><input type="checkbox" name="check-done-${i}" aria-label="Hoàn thành mục ${i+1}" ${c.done?'checked':''}><input name="check-text-${i}" aria-label="Nội dung mục ${i+1}" maxlength="300" required value="${esc(c.text)}"><label>Bắt đầu<input type="datetime-local" name="check-start-${i}" value="${esc(c.start||'')}"></label><label>Kết thúc<input type="datetime-local" name="check-end-${i}" value="${esc(c.end||'')}"></label><label><input type="checkbox" name="check-remove-${i}">Xóa mục</label></div>`).join('')+'<label class="field">Thêm checklist (mỗi dòng một mục)<textarea name="extra-checks" maxlength="20000"></textarea></label><p class="help-copy">Chỉnh trực tiếp các trường, rồi chọn Lưu thay đổi. Chuyển sang cột tiếp theo cũng lưu nội dung đang chỉnh.</p>');const submit=form.onsubmit;const wrapper=e=>{e.preventDefault();const fd=new FormData(form),original=structuredClone(t.checks),updated=[];for(let i=0;i<t.checks.length;i++){const c=t.checks[i];if(fd.has('check-remove-'+i))continue;const start=fd.get('check-start-'+i)||'',end=fd.get('check-end-'+i)||'';if(start&&end&&start>end)return notify('Kết thúc checklist phải sau bắt đầu.');updated.push({...c,text:String(fd.get('check-text-'+i)||'').trim(),done:fd.has('check-done-'+i),start,end});}const extra=String(fd.get('extra-checks')||'').split('\n').map(s=>s.trim()).filter(Boolean);if(updated.length+extra.length>200)return notify('Tối đa 200 mục checklist.');const before=structuredClone(data);t.checks=[...updated,...extra.map(text=>({id:uid(),text:text.slice(0,300),done:false}))];moveToTrash(before);if(!fd.get('title').trim()||!validDate(fd.get('due'))||(fd.get('start')&&fd.get('end')&&fd.get('start')>fd.get('end'))){t.checks=original;data.trash=before.trash;return notify('Kiểm tra tên và khoảng thời gian công việc.');}if(form.elements.col.value===t.col&&updated.length&&!extra.length&&!original.every(c=>c.done)&&updated.every(c=>c.done))form.elements.col.value='Done';else if(t.col==='Done'&&form.elements.col.value==='Done'&&updated.some(c=>!c.done))form.elements.col.value=p.columns.includes('Doing')?'Doing':p.columns[0];submit(e);if(form.onsubmit===wrapper){t.checks=original;data.trash=before.trash;} };form.onsubmit=wrapper;if(next)$('#detail-next').onclick=()=>{form.elements.col.value=next;form.requestSubmit();};};
// taskForm calls taskDetail only after saving, so the editor remains a single screen.
document.addEventListener('change',e=>{const key=e.target.dataset.kanbanOption;if(key){localWrite('kanban-'+key,e.target.checked?'on':'off');render();}});
help=function(){modal(`<h2>Một nơi để nhìn rõ và làm từng việc</h2><div class="help-copy guide-copy"><p>Zen Studio giúp bạn đặt ý tưởng xuống, chọn điều cần làm và nhìn thấy tiến bộ. Tiến độ là thông tin để điều chỉnh nhịp làm việc, không phải thước đo giá trị của bạn.</p><h3>1. Bắt đầu từ toàn cảnh</h3><p>Tổng quan tập hợp các dự án đang hoạt động. Bức tranh công việc cho biết tổng số việc, số đã xong, đang làm, đang chờ và quá hạn. Quá hạn là việc chưa ở Done và đã qua ngày kết thúc hoặc hạn hoàn thành; biểu đồ đưa việc quá hạn vào nhóm đỏ riêng để không đếm trùng. Rê chuột hoặc chạm vào từng màu để xem chi tiết.</p><h3>2. Dự án và Kanban</h3><p>Mỗi tab là một dự án. Ghim để thu nhỏ tab, vẫn giữ phần trăm tiến độ; bấm tab để đổi dự án ngay trong chế độ đang xem. Kéo thẻ giữa các cột hoặc mở task và chọn Chuyển sang cột kế tiếp. Bạn có thể thêm cột riêng. Tùy chọn phía trên bảng cho phép ẩn hoặc hiện thanh tiến độ và checklist trên thẻ; tùy chọn được nhớ trên thiết bị.</p><h3>3. Chỉnh công việc tại một màn hình</h3><p>Bấm task để sửa tên, mô tả, cột, hạn, giờ bắt đầu/kết thúc, ma trận và từ khóa. Checklist có nội dung, trạng thái, lịch riêng và tùy chọn xóa. Bấm Lưu thay đổi để áp dụng; nút chuyển bước cũng lưu các trường đang chỉnh. Chuyển sang Done đánh dấu toàn bộ checklist hoàn tất. Tệp đính kèm mở kho tệp riêng tư.</p><h3>4. Bốn cách chọn ưu tiên</h3><p><b>Quan trọng, khẩn cấp</b> (tím): xử lý trước. <b>Quan trọng, không khẩn cấp</b> (xanh lá): lên kế hoạch. <b>Không quan trọng, khẩn cấp</b> (hồng): cân nhắc ủy quyền. <b>Không quan trọng, không khẩn cấp</b> (cam): để sau. Nhãn có chữ và màu viền để dễ phân biệt. Bạn có thể dùng nhãn riêng trong công việc.</p><h3>5. Tiến độ và lịch</h3><p>Tiến độ task tính theo checklist; task không có checklist dựa vào trạng thái Done. Tiến độ dự án tính mỗi task và mỗi mục checklist là một đơn vị. Timeline sắp công việc và checklist theo lịch; Calendar hiển thị lịch tháng. Thanh tiến độ xuất hiện ở cả hai chế độ. Bấm một mục để mở task gốc. Việc chưa đặt ngày nằm trong Timeline.</p><h3>6. Ghi chú, tệp và Thùng rác</h3><p>Ghi chú dùng để giữ ý tưởng, liên kết và tài liệu. Tệp tối đa 25 MB, kho Kanban giới hạn 1 GB gồm cả Thùng rác và tệp đang tải. Dữ liệu xóa được giữ 30 ngày để khôi phục trước khi tự dọn. Có thể lưu trữ dự án đang làm dở; trạng thái, checklist và tệp được giữ để khôi phục khi cần. Dự án lưu trữ không được nhắc hạn.</p><h3>7. Đồng bộ và thông báo</h3><p>Biểu tượng xanh báo đã đồng bộ; vàng báo cần chú ý kết nối. Thay đổi ngoại tuyến chờ gửi khi có mạng. Chuông tập hợp việc quan trọng, sắp hạn, quá hạn, tệp mới và phiên bản. Đã xem tất cả xóa bộ đếm hiện tại; thông báo mới được đếm lại. Email nhắc trước hạn 3 ngày, ngày đến hạn và quá hạn mỗi ngày theo giờ đã chọn. Trong Settings, bật tổng kết Chủ nhật và nhắc lặp trong ứng dụng; có thể xem trước nội dung tổng kết.</p><h3>8. Giữ dữ liệu an toàn</h3><p>Xuất JSON định kỳ trong Settings. Khi có xung đột đồng bộ, xuất bản trên máy trước khi chọn dữ liệu máy chủ. Đăng xuất sau khi đồng bộ xong trên thiết bị dùng chung. Lời chào hằng ngày có câu trích dẫn tiếng Việt và liên kết nguồn.</p></div>`,null,true);};
document.addEventListener('click',e=>{if(!e.target.closest('[data-files]')||!$('#editor-body .inline-check')&&!$('#editor-body #detail-next'))return;const f=$('#editor-form'),prior=f.onsubmit;f.requestSubmit();if(f.onsubmit===prior){e.preventDefault();e.stopImmediatePropagation();}},true);
